import type { Href } from 'expo-router';

import type { EmailVerificationChallenge } from '../api/types/auth';

/**
 * The verify-email screen for a challenge from register (201) or sign-in
 * (403 `email_unverified`), with its clocks seeded from the API's numbers.
 *
 * Typed routes are regenerated by `expo start`; the cast keeps a fresh
 * checkout compiling before that has run once (as in `location/picker.ts`).
 */
export function verifyEmailRoute(challenge: EmailVerificationChallenge): Href {
  return {
    pathname: '/(auth)/verify-email',
    params: {
      email: challenge.email,
      resend: String(challenge.resend_available_in),
      expires: String(challenge.expires_in),
      sent: challenge.otp_sent ? '1' : '0',
    },
  } as unknown as Href;
}
